"""
setup_project.py
----------------
Creates the full leetcode-ai-sync project folder structure and writes
all starter files in one go. Run this once from wherever you want the
project folder to be created.

Usage:
    python setup_project.py
"""

import os
from pathlib import Path

PROJECT_ROOT = Path("leetcode-ai-sync")

FILES = {}

FILES['.env.example'] = '# Copy this file to .env for local testing (never commit the real .env!)\n\nLEETCODE_SESSION=your_leetcode_session_cookie\nLEETCODE_CSRF=your_csrftoken_cookie\nLEETCODE_USERNAME=your_leetcode_username\n\nGEMINI_API_KEY=your_gemini_api_key\n'

FILES['.github/workflows/sync.yml'] = 'name: Sync LeetCode Submissions\n\non:\n  schedule:\n    # Runs every 6 hours. Adjust as you like.\n    - cron: "0 */6 * * *"\n  workflow_dispatch: {}   # allows manual trigger from the Actions tab\n\npermissions:\n  contents: write\n\njobs:\n  sync:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout repo\n        uses: actions/checkout@v4\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: "3.11"\n\n      - name: Install dependencies\n        run: pip install -r requirements.txt\n\n      - name: Run LeetCode sync\n        id: sync\n        env:\n          LEETCODE_SESSION: ${{ secrets.LEETCODE_SESSION }}\n          LEETCODE_CSRF: ${{ secrets.LEETCODE_CSRF }}\n          LEETCODE_USERNAME: ${{ secrets.LEETCODE_USERNAME }}\n        run: python scripts/sync_leetcode.py | tee sync_output.txt\n\n      - name: Enrich new solutions with AI\n        env:\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\n        run: |\n          # Extract folder paths printed by sync_leetcode.py (lines starting with "  - ")\n          grep "^  - " sync_output.txt | sed \'s/^  - //\' > new_folders.txt || true\n          if [ -s new_folders.txt ]; then\n            python scripts/enrich.py $(cat new_folders.txt)\n          else\n            echo "No new folders to enrich."\n          fi\n\n      - name: Update RAG vector store\n        env:\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\n        run: python rag/ingest.py\n\n      - name: Commit and push changes\n        run: |\n          git config user.name "leetcode-sync-bot"\n          git config user.email "actions@github.com"\n          git add leetcode-questions/ data/\n          git diff --staged --quiet || git commit -m "chore: sync LeetCode submissions [automated]"\n          git push\n'

FILES['.gitignore'] = 'venv/\n__pycache__/\n*.pyc\n.env\ndata/chroma_store/\nsync_output.txt\nnew_folders.txt\n'

FILES['README.md'] = '# 🧠 LeetCode AI Sync\n\n> Automatically syncs accepted LeetCode submissions to GitHub, enriches each one\n> with AI-generated explanations and complexity analysis, and exposes the whole\n> archive as a queryable RAG knowledge base.\n\n![Python](https://img.shields.io/badge/Python-3.11-blue?logo=python&logoColor=white)\n![Gemini](https://img.shields.io/badge/AI-Gemini%202.5-orange?logo=google&logoColor=white)\n![ChromaDB](https://img.shields.io/badge/VectorDB-ChromaDB-green)\n![GitHub Actions](https://img.shields.io/badge/Automation-GitHub%20Actions-2088FF?logo=githubactions&logoColor=white)\n![License](https://img.shields.io/badge/License-MIT-lightgrey)\n\n---\n\n## Why this exists\n\nSolving LeetCode problems is only half the value — the other half is remembering\n*how* you solved them, *why* that approach worked, and being able to recognize\nthe same pattern next time it shows up. This project closes that loop:\n\n1. Every accepted submission is automatically pulled into a structured GitHub repo\n2. Each solution is enriched by an LLM with an explanation, complexity analysis,\n   and pattern tag — turning a bare code file into a study artifact\n3. The whole archive becomes searchable via RAG, so you can ask\n   *"have I solved anything like this before?"* and actually get an answer\n\n---\n\n## Architecture\n\n```mermaid\nflowchart TD\n    A[LeetCode Account] -->|GraphQL API| B[sync_leetcode.py]\n    B -->|writes| C[leetcode-questions/ repo folder]\n    B -->|tracks synced IDs| D[(synced_submissions.json)]\n\n    C --> E[enrich.py]\n    E -->|Gemini 2.5 Flash-Lite| F[Enriched README.md<br/>approach + complexity + pattern]\n\n    F --> G[ingest.py]\n    G -->|Gemini Embeddings| H[(ChromaDB Vector Store)]\n\n    H --> I[query.py / RAG CLI]\n    I -->|semantic search + LLM answer| J[You, asking:<br/>\'Have I solved anything like this?\']\n\n    K[GitHub Actions<br/>cron: every 6h] -.triggers.-> B\n    K -.triggers.-> E\n    K -.triggers.-> G\n\n    style A fill:#FFA116,color:#000\n    style H fill:#4CAF50,color:#fff\n    style J fill:#2196F3,color:#fff\n    style K fill:#2088FF,color:#fff\n```\n\n---\n\n## Pipeline stages\n\n```mermaid\nsequenceDiagram\n    participant LC as LeetCode\n    participant GH as GitHub Actions (cron)\n    participant Sync as sync_leetcode.py\n    participant Enrich as enrich.py (Gemini)\n    participant Repo as leetcode-questions/\n    participant Vec as ChromaDB\n\n    GH->>Sync: trigger every 6h\n    Sync->>LC: query recentAcSubmissionList\n    LC-->>Sync: new accepted submissions\n    Sync->>Repo: write solution.py + base README.md\n    Sync->>Sync: save synced_submissions.json (incremental)\n\n    GH->>Enrich: run on new folders\n    Enrich->>Enrich: prompt Gemini with code + metadata\n    Enrich->>Repo: overwrite README.md with approach, complexity, pattern, improvements\n\n    GH->>Vec: ingest.py embeds enriched docs\n    Vec-->>Vec: upsert by folder path (idempotent)\n\n    Note over Repo,Vec: You can now query your own archive semantically via rag/query.py\n```\n\n---\n\n## Project structure\n\n```\nleetcode-ai-sync/\n├── .github/workflows/sync.yml      # runs the full pipeline every 6 hours\n├── scripts/\n│   ├── sync_leetcode.py             # Phase 1 — LeetCode → repo\n│   ├── enrich.py                    # Phase 2 — AI enrichment\n│   └── stats.py                     # pattern/difficulty breakdown + chart data\n├── rag/\n│   ├── ingest.py                    # Phase 3 — embed into ChromaDB\n│   └── query.py                     # Phase 3 — RAG chat over your archive\n├── leetcode-questions/               # auto-generated, organized by tag\n│   └── Linked_List/\n│       └── 2095-delete-the-middle-node-of-a-linked-list/\n│           ├── solution.py\n│           └── README.md             # AI-enriched\n├── data/\n│   ├── synced_submissions.json       # dedup tracking (saved incrementally)\n│   ├── stats.json                    # generated by stats.py\n│   └── chroma_store/                  # local vector DB\n├── requirements.txt\n├── setup_project.py                  # one-shot scaffolder for this whole repo\n└── .env.example\n```\n\n---\n\n## Tech stack & why each piece was chosen\n\n| Layer | Tool | Why |\n|---|---|---|\n| Data source | LeetCode GraphQL (internal API) | No official public API exists; this is the same endpoint the LeetCode frontend itself uses |\n| Automation | GitHub Actions (cron) | Zero hosting cost, runs natively where the repo lives |\n| LLM enrichment | Gemini 2.5 Flash-Lite | Fast, generous free-tier daily quota, good enough quality for structured explanation generation |\n| Vector store | ChromaDB | Lightweight, file-based, no external service needed for a personal-scale archive |\n| Embeddings | `gemini-embedding-001` | Same provider as generation, avoids juggling two API keys |\n| RAG interface | Rich-based CLI | Fast to build, focuses effort on the retrieval logic rather than UI chrome |\n\n---\n\n## How it works, end to end\n\n### 1. Sync — `scripts/sync_leetcode.py`\nPolls `recentAcSubmissionList` via LeetCode\'s GraphQL endpoint using your session\ncookies, fetches the actual code for each new accepted submission via\n`submissionDetails`, and fetches problem metadata (difficulty, tags, title) via\nthe `question` query. Writes everything into\n`leetcode-questions/<primary-tag>/<id>-<slug>/`. Tracks synced submission IDs in\n`data/synced_submissions.json`, saved **incrementally after each submission** —\nso an interrupted run never loses progress or causes duplicate API calls.\n\n### 2. Enrich — `scripts/enrich.py`\nFor each new solution folder, sends the code + metadata to Gemini with a\nstructured prompt and parses back four fixed sections: **Approach**,\n**Complexity**, **Pattern**, and **Could it be improved?**. This turns a bare\nsolution file into something genuinely reviewable — the same way a senior\nengineer would annotate a PR.\n\n### 3. Ingest — `rag/ingest.py`\nWalks the enriched repo and embeds each problem\'s full README + code into a\nlocal ChromaDB collection, keyed by folder path so re-running is idempotent\n(`upsert`, not `insert`).\n\n### 4. Query — `rag/query.py`\nA RAG loop: embed the question → retrieve top-k similar problems → pass them\nas context to Gemini → get a grounded answer referencing your actual past\nsolutions, not a generic LeetCode explanation.\n\n---\n\n## Setup\n\n```bash\n# 1. Clone and enter the project\ncd leetcode-ai-sync\n\n# 2. Create a virtual environment (Python 3.11 recommended)\nuv venv --python 3.11\n.\\venv\\Scripts\\Activate        # Windows\n# source venv/bin/activate     # macOS/Linux\n\n# 3. Install dependencies\nuv pip install -r requirements.txt\n\n# 4. Configure credentials\ncp .env.example .env\n# Fill in LEETCODE_SESSION, LEETCODE_CSRF, LEETCODE_USERNAME, GEMINI_API_KEY\n```\n\n**Getting LeetCode cookies:** DevTools → Application/Storage → Cookies →\n`leetcode.com` → copy `LEETCODE_SESSION` and `csrftoken`. These expire\nperiodically and need refreshing.\n\n**Getting a Gemini key:** https://aistudio.google.com/apikey\n\n### Run the pipeline manually\n\n```bash\npython scripts/sync_leetcode.py\npython scripts/enrich.py leetcode-questions/<folder-printed-above>\npython rag/ingest.py\npython rag/query.py\npython scripts/stats.py\n```\n\n### Automate it\n\nAdd `LEETCODE_SESSION`, `LEETCODE_CSRF`, `LEETCODE_USERNAME`, `GEMINI_API_KEY`\nas repo secrets (Settings → Secrets and variables → Actions). The workflow in\n`.github/workflows/sync.yml` then runs the full pipeline every 6 hours and\ncommits the results automatically.\n\n---\n\n## Example output\n\n**Auto-generated README for a synced solution:**\n\n```markdown\n# 54. Spiral Matrix\n**Difficulty:** Medium\n**Tags:** Array, Matrix, Simulation\n\n## Approach\nThe solution simulates the spiral traversal by maintaining four pointers —\ntop, bottom, left, right — that define the current boundaries of the\nunvisited portion of the matrix...\n\n## Complexity\n- Time: O(m * n)\n- Space: O(m * n)\n\n## Pattern\nSimulation\n\n## Could it be improved?\nThe current approach is optimal in both time and space — no fundamentally\nmore efficient algorithm exists for this problem.\n```\n\n**RAG query in action:**\n\n```\n> Have I solved anything involving linked lists?\n\nYes, you have solved two problems involving linked lists:\n • 2095. Delete the Middle Node of a Linked List\n • 2130. Maximum Twin Sum of a Linked List\n```\n\n---\n\n## My LeetCode profile, pulled live\n\nRun `python scripts/profile_stats.py` any time to refresh this — it pulls your\nreal account totals straight from LeetCode and regenerates the dashboard below.\n\n| Metric | Value |\n|---|---|\n| Total solved | **190** |\n| Acceptance rate | **82.1%** |\n| Global ranking | **#845,158** |\n| Badges earned | 5 (incl. 100 Days Badge 2025) |\n\n| Difficulty | Solved | Available | % cleared |\n|---|---|---|---|\n| Easy | 62 | 951 | 6.5% |\n| Medium | 95 | 2,074 | 4.6% |\n| Hard | 33 | 948 | 3.5% |\n\n![LeetCode Dashboard](data/profile_dashboard.png)\n\n> This is pulled directly via LeetCode\'s GraphQL API, the same one used for\n> the sync pipeline above — so the same auth cookies power both features.\n\n---\n\n## Repo-local solve stats\n\nThis is a separate, narrower view — only the problems that have actually been\nsynced into *this* repo via the pipeline (run `python scripts/stats.py` to\nrefresh):\n\n```\nTotal problems solved & synced: 20\nBy Difficulty:   Medium 9 · Hard 7 · Easy 4\nBy Tag:          Array 8 · Misc 4 · Linked_List 2 · Math 2 · String 2 · DP 1 · Hash_Table 1\n```\n\nThe gap between this and the full profile above is expected — this repo only\ncaptures what\'s been solved *since the pipeline started running*. Every future\nsubmission grows this number automatically.\n\n\n\n- [x] Phase 1 — automated sync from LeetCode to GitHub\n- [x] Phase 2 — LLM enrichment (approach, complexity, pattern, improvements)\n- [x] Phase 3 — RAG query over the solved-problems archive\n- [x] GitHub Actions automation (runs every 6 hours, zero manual upkeep)\n- [ ] Phase 4 — multi-agent enrichment pipeline (categorizer → explainer →\n      reviewer → indexer agents via LangChain, instead of a single prompt)\n- [ ] Web chat UI (React/Vite) replacing the CLI for the RAG step\n- [ ] Weekly auto-generated "patterns I\'m weak on" summary from vector store\n      clustering\n- [ ] Real-time sync via a Chrome extension instead of polling\n\n---\n\n## Notes & limitations\n\n- LeetCode has no official public API; this relies on the same internal\n  GraphQL endpoint the website itself uses, authenticated via session cookies.\n  These cookies expire periodically and must be refreshed manually.\n- Gemini\'s free tier enforces a daily request quota; enriching large batches\n  in one sitting may require spacing requests out or switching to\n  `gemini-2.5-flash-lite`, which has a more generous daily limit.\n- This project is intended for personal use against your own LeetCode account\n  — it is not designed or licensed for scraping other users\' submissions.\n\n---\n\n## License\n\nMIT — use freely, attribution appreciated.\n'

FILES['rag/ingest.py'] = '"""\ningest.py\n---------\nWalks the leetcode-questions/ folder, reads each enriched README.md + solution\nfile, and embeds it into a local ChromaDB collection so you can later query\nyour own solved problems semantically (see query.py).\n\nRun this after enrich.py, or just re-run it on the whole repo periodically\n(it\'s idempotent — re-ingesting a folder overwrites its existing entry).\n"""\n\nimport os\nfrom pathlib import Path\nimport chromadb\nfrom chromadb.config import Settings\nfrom chromadb.utils import embedding_functions\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nREPO_ROOT = Path(__file__).parent.parent / "leetcode-questions"\nCHROMA_PATH = Path(__file__).parent.parent / "data" / "chroma_store"\n\nGEMINI_API_KEY = os.environ.get("GEMINI_API_KEY")\n\nclient = chromadb.PersistentClient(\n    path=str(CHROMA_PATH), settings=Settings(anonymized_telemetry=False)\n)\n\n# Use Gemini embeddings if key is present, otherwise fall back to a local\n# sentence-transformers model (no API key needed, slightly lower quality).\nif GEMINI_API_KEY:\n    embedding_fn = embedding_functions.GoogleGenerativeAiEmbeddingFunction(\n        api_key=GEMINI_API_KEY, model_name="models/gemini-embedding-001"\n    )\nelse:\n    embedding_fn = embedding_functions.SentenceTransformerEmbeddingFunction(\n        model_name="all-MiniLM-L6-v2"\n    )\n\ncollection = client.get_or_create_collection(\n    name="leetcode_solutions", embedding_function=embedding_fn\n)\n\n\ndef build_document_text(folder: Path) -> str | None:\n    readme = folder / "README.md"\n    if not readme.exists():\n        return None\n    sol_files = list(folder.glob("solution.*"))\n    code = sol_files[0].read_text() if sol_files else ""\n    return f"{readme.read_text()}\\n\\n---\\nCode:\\n{code}"\n\n\ndef ingest_all():\n    count = 0\n    for tag_folder in REPO_ROOT.iterdir():\n        if not tag_folder.is_dir():\n            continue\n        for problem_folder in tag_folder.iterdir():\n            if not problem_folder.is_dir():\n                continue\n            doc_text = build_document_text(problem_folder)\n            if not doc_text:\n                continue\n\n            doc_id = str(problem_folder.relative_to(REPO_ROOT))\n            collection.upsert(\n                ids=[doc_id],\n                documents=[doc_text],\n                metadatas=[{\n                    "tag": tag_folder.name,\n                    "path": doc_id,\n                }],\n            )\n            count += 1\n    print(f"Ingested/updated {count} problems into ChromaDB at {CHROMA_PATH}")\n\n\nif __name__ == "__main__":\n    ingest_all()\n'

FILES['rag/query.py'] = '"""\nquery.py\n--------\nSimple CLI chat over your embedded LeetCode solutions.\n\nUsage:\n    python rag/query.py\n    > Have I solved anything like "container with most water"?\n    > Show me all my sliding window problems\n"""\n\nimport os\nfrom pathlib import Path\nimport chromadb\nfrom chromadb.config import Settings\nfrom chromadb.utils import embedding_functions\nimport google.generativeai as genai\nfrom rich.console import Console\nfrom rich.markdown import Markdown\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nconsole = Console()\n\nGEMINI_API_KEY = os.environ.get("GEMINI_API_KEY")\nCHROMA_PATH = Path(__file__).parent.parent / "data" / "chroma_store"\n\ngenai.configure(api_key=GEMINI_API_KEY)\nclient = chromadb.PersistentClient(\n    path=str(CHROMA_PATH), settings=Settings(anonymized_telemetry=False)\n)\n\nif GEMINI_API_KEY:\n    embedding_fn = embedding_functions.GoogleGenerativeAiEmbeddingFunction(\n        api_key=GEMINI_API_KEY, model_name="models/gemini-embedding-001"\n    )\nelse:\n    embedding_fn = embedding_functions.SentenceTransformerEmbeddingFunction(\n        model_name="all-MiniLM-L6-v2"\n    )\n\ncollection = client.get_or_create_collection(\n    name="leetcode_solutions", embedding_function=embedding_fn\n)\n\nANSWER_PROMPT = """You are an assistant that helps a software engineering student\nrecall their own past LeetCode solutions. Based ONLY on the context below\n(retrieved from their personal solved-problems archive), answer their question.\nIf nothing relevant is found, say so honestly.\n\nContext:\n{context}\n\nQuestion: {question}\n\nAnswer concisely, referencing problem names/paths where relevant.\n"""\n\n\ndef retrieve(question: str, k: int = 5):\n    results = collection.query(query_texts=[question], n_results=k)\n    docs = results.get("documents", [[]])[0]\n    metas = results.get("metadatas", [[]])[0]\n    return list(zip(docs, metas))\n\n\ndef answer(question: str) -> str:\n    matches = retrieve(question)\n    if not matches:\n        return "No solved problems found in your archive yet — run ingest.py first."\n\n    context = "\\n\\n---\\n\\n".join(\n        f"[{meta[\'path\']}]\\n{doc[:1500]}" for doc, meta in matches\n    )\n    model = genai.GenerativeModel("gemini-2.5-flash-lite")\n    prompt = ANSWER_PROMPT.format(context=context, question=question)\n    try:\n        response = model.generate_content(prompt)\n        return response.text.strip()\n    except Exception as e:\n        return f"Gemini request failed (likely rate limit) — try again in a moment.\\nDetails: {e}"\n\n\ndef main():\n    console.print("[bold cyan]LeetCode RAG Assistant[/bold cyan] — ask about your solved problems. Ctrl+C to quit.\\n")\n    while True:\n        try:\n            question = console.input("[bold green]> [/bold green]")\n        except (KeyboardInterrupt, EOFError):\n            break\n        if not question.strip():\n            continue\n        result = answer(question)\n        console.print(Markdown(result))\n        console.print()\n\n\nif __name__ == "__main__":\n    main()\n'

FILES['requirements.txt'] = '# --- Core / HTTP ---\nrequests==2.32.3\npython-dotenv==1.0.1\n\n# --- GitHub integration ---\nPyGithub==2.4.0\nGitPython==3.1.43\n\n# --- GenAI / LLM ---\ngoogle-generativeai==0.8.3\nlangchain==0.3.7\nlangchain-community==0.3.5\nlangchain-google-genai==2.0.4\n\n# --- RAG / Vector store ---\nchromadb==0.5.20\nsentence-transformers==3.2.1\n\n# --- Utilities ---\ntqdm==4.66.5\npydantic==2.9.2\ntenacity==9.0.0\n\n# --- Charts ---\nmatplotlib==3.9.2\n\n# --- CLI chat interface (Phase 3) ---\nrich==13.9.3\n'

FILES['scripts/enrich.py'] = '"""\nenrich.py\n---------\nTakes newly-synced solution folders and uses Gemini to:\n  1. Generate a clean explanation of the approach\n  2. Compute/verify time & space complexity\n  3. Suggest a more optimal approach if one exists\n  4. Tag the underlying pattern (sliding window, DP, two pointers, etc.)\n\nThis overwrites README.md in each folder with the enriched version.\nRun this AFTER sync_leetcode.py, passing the folder paths it printed.\n\nRequired env var: GEMINI_API_KEY\n"""\n\nimport os\nimport sys\nfrom pathlib import Path\nimport google.generativeai as genai\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nGEMINI_API_KEY = os.environ.get("GEMINI_API_KEY")\ngenai.configure(api_key=GEMINI_API_KEY)\n\nMODEL_NAME = "gemini-2.5-flash-lite"  # higher free-tier daily quota than gemini-2.5-flash\n\nPROMPT_TEMPLATE = """You are a senior software engineer reviewing a LeetCode solution.\n\nProblem title: {title}\nDifficulty: {difficulty}\nExisting tags: {tags}\n\nSolution code ({lang}):\n```\n{code}\n```\n\nRespond in clean Markdown with EXACTLY these sections:\n\n## Approach\n(2-4 sentences explaining the core idea in plain English)\n\n## Complexity\n- Time: O(...)\n- Space: O(...)\n\n## Pattern\n(One or two words identifying the algorithmic pattern, e.g. "Sliding Window", "Two Pointers", "DP - 1D")\n\n## Could it be improved?\n(If the approach is already optimal, say so briefly. If a better complexity solution\nexists, describe it in 2-3 sentences without writing full code.)\n\nDo not repeat the code. Do not add any other sections.\n"""\n\n\ndef enrich_folder(folder: Path):\n    readme_path = folder / "README.md"\n    if not readme_path.exists():\n        print(f"Skipping {folder}, no README.md found.")\n        return\n\n    # Find the solution file (solution.<ext>)\n    sol_files = list(folder.glob("solution.*"))\n    if not sol_files:\n        print(f"Skipping {folder}, no solution file found.")\n        return\n    code = sol_files[0].read_text()\n    lang = sol_files[0].suffix.lstrip(".")\n\n    original_readme = readme_path.read_text()\n    # crude parse of title/difficulty/tags from the auto-generated README header\n    lines = original_readme.splitlines()\n    title = lines[0].lstrip("# ").strip() if lines else folder.name\n    difficulty = next((l.split(":")[1].strip() for l in lines if l.startswith("**Difficulty:**")), "Unknown")\n    tags = next((l.split(":")[1].strip() for l in lines if l.startswith("**Tags:**")), "N/A")\n\n    model = genai.GenerativeModel(MODEL_NAME)\n    prompt = PROMPT_TEMPLATE.format(\n        title=title, difficulty=difficulty, tags=tags, lang=lang, code=code\n    )\n    try:\n        response = model.generate_content(prompt)\n        enriched_section = response.text.strip()\n    except Exception as e:\n        print(f"  -> Gemini call failed for {folder}: {e}")\n        return\n\n    # Append enrichment, keep original header info\n    final_content = original_readme.split("## My Solution")[0] + f"## My Solution\\n\\nSee `solution.{lang}`\\n\\n" + enriched_section + "\\n"\n    readme_path.write_text(final_content)\n    print(f"Enriched: {readme_path}")\n\n\ndef main(folders: list[str]):\n    if not GEMINI_API_KEY:\n        raise EnvironmentError("Missing GEMINI_API_KEY env var.")\n    for f in folders:\n        enrich_folder(Path(f))\n\n\nif __name__ == "__main__":\n    # Accepts folder paths as CLI args, e.g.:\n    # python enrich.py leetcode-questions/Array/1-two-sum\n    if len(sys.argv) < 2:\n        print("Usage: python enrich.py <folder1> <folder2> ...")\n        sys.exit(1)\n    main(sys.argv[1:])\n'

FILES['scripts/sync_leetcode.py'] = '"""\nsync_leetcode.py\n-----------------\nFetches your recent ACCEPTED LeetCode submissions via the internal GraphQL API,\nand writes any new ones into a structured local folder (which a GitHub Action\nwill later commit + push).\n\nRequired environment variables (set as GitHub Secrets in production,\nor in a local .env file for testing):\n    LEETCODE_SESSION   -> value of the \'LEETCODE_SESSION\' cookie from your browser\n    LEETCODE_CSRF      -> value of the \'csrftoken\' cookie from your browser\n    LEETCODE_USERNAME  -> your LeetCode username\n\nHow to get the cookies:\n    1. Log into leetcode.com in your browser\n    2. Open DevTools -> Application/Storage -> Cookies -> leetcode.com\n    3. Copy the values of \'LEETCODE_SESSION\' and \'csrftoken\'\n    Note: these expire periodically — you\'ll need to refresh them every so often.\n"""\n\nimport os\nimport json\nimport time\nimport requests\nfrom pathlib import Path\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nLEETCODE_SESSION = os.environ.get("LEETCODE_SESSION")\nLEETCODE_CSRF = os.environ.get("LEETCODE_CSRF")\nLEETCODE_USERNAME = os.environ.get("LEETCODE_USERNAME")\n\nGRAPHQL_URL = "https://leetcode.com/graphql"\nREPO_ROOT = Path(__file__).parent.parent / "leetcode-questions"\nSTATE_FILE = Path(__file__).parent.parent / "data" / "synced_submissions.json"\n\nHEADERS = {\n    "Content-Type": "application/json",\n    "Referer": "https://leetcode.com",\n    "Cookie": f"LEETCODE_SESSION={LEETCODE_SESSION}; csrftoken={LEETCODE_CSRF};",\n    "x-csrftoken": LEETCODE_CSRF or "",\n}\n\nLANG_EXTENSION_MAP = {\n    "python3": "py", "python": "py", "java": "java", "cpp": "cpp",\n    "c": "c", "csharp": "cs", "javascript": "js", "typescript": "ts",\n    "golang": "go", "kotlin": "kt", "swift": "swift", "rust": "rs",\n    "ruby": "rb", "scala": "scala", "php": "php",\n}\n\n\ndef load_synced_state() -> dict:\n    if STATE_FILE.exists():\n        return json.loads(STATE_FILE.read_text())\n    return {}\n\n\ndef save_synced_state(state: dict) -> None:\n    STATE_FILE.parent.mkdir(parents=True, exist_ok=True)\n    STATE_FILE.write_text(json.dumps(state, indent=2))\n\n\ndef fetch_recent_accepted_submissions(limit: int = 20) -> list[dict]:\n    """Fetches your most recent accepted submissions (lightweight list, no code)."""\n    query = """\n    query recentAcSubmissions($username: String!, $limit: Int!) {\n        recentAcSubmissionList(username: $username, limit: $limit) {\n            id\n            title\n            titleSlug\n            timestamp\n            lang\n        }\n    }\n    """\n    payload = {\n        "query": query,\n        "variables": {"username": LEETCODE_USERNAME, "limit": limit},\n    }\n    resp = requests.post(GRAPHQL_URL, json=payload, headers=HEADERS, timeout=15)\n    resp.raise_for_status()\n    data = resp.json()\n    return data.get("data", {}).get("recentAcSubmissionList", []) or []\n\n\ndef fetch_submission_code(submission_id: str) -> str | None:\n    """Fetches the actual submitted code for a given submission id."""\n    query = """\n    query submissionDetails($submissionId: Int!) {\n        submissionDetails(submissionId: $submissionId) {\n            code\n            lang { name }\n        }\n    }\n    """\n    payload = {"query": query, "variables": {"submissionId": int(submission_id)}}\n    resp = requests.post(GRAPHQL_URL, json=payload, headers=HEADERS, timeout=15)\n    resp.raise_for_status()\n    data = resp.json()\n    details = data.get("data", {}).get("submissionDetails")\n    return details.get("code") if details else None\n\n\ndef fetch_problem_metadata(title_slug: str) -> dict:\n    """Fetches difficulty, tags, and the problem statement for a problem."""\n    query = """\n    query questionData($titleSlug: String!) {\n        question(titleSlug: $titleSlug) {\n            questionFrontendId\n            title\n            difficulty\n            content\n            topicTags { name }\n        }\n    }\n    """\n    payload = {"query": query, "variables": {"titleSlug": title_slug}}\n    resp = requests.post(GRAPHQL_URL, json=payload, headers=HEADERS, timeout=15)\n    resp.raise_for_status()\n    data = resp.json()\n    return data.get("data", {}).get("question", {}) or {}\n\n\ndef slugify_folder(frontend_id: str, title_slug: str) -> str:\n    return f"{frontend_id}-{title_slug}"\n\n\ndef write_solution_files(meta: dict, code: str, lang: str) -> Path:\n    """Writes solution.<ext> and a metadata README.md into the right folder."""\n    difficulty = meta.get("difficulty", "Unknown")\n    tags = [t["name"] for t in meta.get("topicTags", [])]\n    primary_tag = tags[0] if tags else "Misc"\n    frontend_id = meta.get("questionFrontendId", "0")\n    title = meta.get("title", "untitled")\n    title_slug = title.lower().replace(" ", "-")\n\n    folder = REPO_ROOT / primary_tag.replace(" ", "_") / slugify_folder(frontend_id, title_slug)\n    folder.mkdir(parents=True, exist_ok=True)\n\n    ext = LANG_EXTENSION_MAP.get(lang.lower(), "txt")\n    (folder / f"solution.{ext}").write_text(code)\n\n    readme = f"""# {frontend_id}. {title}\n\n**Difficulty:** {difficulty}\n**Tags:** {", ".join(tags) if tags else "N/A"}\n**Language:** {lang}\n\n## Problem\n\nSee: https://leetcode.com/problems/{title_slug}/\n\n## My Solution\n\nSee `solution.{ext}`\n\n> _AI-generated explanation, complexity analysis, and pattern tagging are added\n> by `scripts/enrich.py` in a later step of the pipeline._\n"""\n    (folder / "README.md").write_text(readme)\n    return folder\n\n\ndef run_sync():\n    if not (LEETCODE_SESSION and LEETCODE_CSRF and LEETCODE_USERNAME):\n        raise EnvironmentError(\n            "Missing one of LEETCODE_SESSION / LEETCODE_CSRF / LEETCODE_USERNAME env vars."\n        )\n\n    state = load_synced_state()\n    submissions = fetch_recent_accepted_submissions(limit=20)\n    new_folders = []\n\n    for sub in submissions:\n        sub_id = sub["id"]\n        if sub_id in state:\n            continue  # already synced\n\n        print(f"New accepted submission found: {sub[\'title\']} ({sub[\'lang\']})")\n        code = fetch_submission_code(sub_id)\n        if not code:\n            print(f"  -> Could not fetch code for {sub[\'title\']}, skipping.")\n            continue\n\n        meta = fetch_problem_metadata(sub["titleSlug"])\n        folder = write_solution_files(meta, code, sub["lang"])\n        new_folders.append(str(folder))\n\n        state[sub_id] = {\n            "title": sub["title"],\n            "timestamp": sub["timestamp"],\n            "synced_at": int(time.time()),\n        }\n        save_synced_state(state)  # persist immediately so an interruption doesn\'t lose progress\n        time.sleep(1)  # be polite to LeetCode\'s servers\n\n    if new_folders:\n        print(f"\\nSynced {len(new_folders)} new solution(s):")\n        for f in new_folders:\n            print(f"  - {f}")\n    else:\n        print("No new accepted submissions since last sync.")\n\n    return new_folders\n\n\nif __name__ == "__main__":\n    run_sync()\n'

FILES['scripts/stats.py'] = '"""\nstats.py\n--------\nAnalyzes your solved-problems archive and prints a breakdown by tag/pattern\nand difficulty. Also writes stats.json so the README/dashboard can render\nit as a chart.\n\nUsage:\n    python scripts/stats.py\n"""\n\nimport json\nimport re\nfrom collections import Counter\nfrom pathlib import Path\n\nREPO_ROOT = Path(__file__).parent.parent / "leetcode-questions"\nSTATS_FILE = Path(__file__).parent.parent / "data" / "stats.json"\n\n\ndef parse_readme(readme_path: Path) -> dict:\n    text = readme_path.read_text(encoding="utf-8")\n    difficulty = re.search(r"\\*\\*Difficulty:\\*\\*\\s*(\\w+)", text)\n    pattern = re.search(r"## Pattern\\s*\\n+(.+)", text)\n    return {\n        "difficulty": difficulty.group(1) if difficulty else "Unknown",\n        "pattern": pattern.group(1).strip() if pattern else "Unknown",\n    }\n\n\ndef collect_stats():\n    difficulty_counter = Counter()\n    pattern_counter = Counter()\n    tag_counter = Counter()\n    total = 0\n\n    for tag_folder in REPO_ROOT.iterdir():\n        if not tag_folder.is_dir():\n            continue\n        for problem_folder in tag_folder.iterdir():\n            readme = problem_folder / "README.md"\n            if not readme.exists():\n                continue\n            total += 1\n            tag_counter[tag_folder.name] += 1\n            info = parse_readme(readme)\n            difficulty_counter[info["difficulty"]] += 1\n            pattern_counter[info["pattern"]] += 1\n\n    return {\n        "total_problems": total,\n        "by_difficulty": dict(difficulty_counter),\n        "by_pattern": dict(pattern_counter),\n        "by_tag": dict(tag_counter),\n    }\n\n\ndef print_bar_chart(title: str, counts: dict):\n    print(f"\\n{title}")\n    print("-" * len(title))\n    if not counts:\n        print("  (no data)")\n        return\n    max_count = max(counts.values())\n    for label, count in sorted(counts.items(), key=lambda x: -x[1]):\n        bar = "█" * int((count / max_count) * 30)\n        print(f"  {label:<25} {bar} {count}")\n\n\ndef main():\n    stats = collect_stats()\n\n    STATS_FILE.parent.mkdir(parents=True, exist_ok=True)\n    STATS_FILE.write_text(json.dumps(stats, indent=2))\n\n    print(f"Total problems solved & synced: {stats[\'total_problems\']}")\n    print_bar_chart("By Difficulty", stats["by_difficulty"])\n    print_bar_chart("By Pattern", stats["by_pattern"])\n    print_bar_chart("By LeetCode Tag", stats["by_tag"])\n    print(f"\\nStats saved to: {STATS_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n'

FILES['scripts/profile_stats.py'] = '"""\nprofile_stats.py\n----------------\nFetches your overall LeetCode profile via GraphQL (total solved by difficulty,\nacceptance rate, ranking, badges) and renders it both as a CLI summary and as\na saved PNG dashboard chart.\n\nThis is DIFFERENT from stats.py:\n    - stats.py    -> analyzes problems already synced into THIS repo\n    - profile_stats.py -> pulls your real, full LeetCode account totals\n      (including problems solved outside this pipeline, e.g. before you\n      started this project)\n\nUsage:\n    python scripts/profile_stats.py\n"""\n\nimport os\nimport requests\nimport matplotlib.pyplot as plt\nfrom pathlib import Path\nfrom dotenv import load_dotenv\nfrom rich.console import Console\nfrom rich.table import Table\nfrom rich.panel import Panel\n\nload_dotenv()\nconsole = Console()\n\nLEETCODE_USERNAME = os.environ.get("LEETCODE_USERNAME")\nLEETCODE_SESSION = os.environ.get("LEETCODE_SESSION")\nLEETCODE_CSRF = os.environ.get("LEETCODE_CSRF")\n\nGRAPHQL_URL = "https://leetcode.com/graphql"\nHEADERS = {\n    "Content-Type": "application/json",\n    "Referer": "https://leetcode.com",\n    "Cookie": f"LEETCODE_SESSION={LEETCODE_SESSION}; csrftoken={LEETCODE_CSRF};",\n    "x-csrftoken": LEETCODE_CSRF or "",\n}\n\nOUTPUT_CHART = Path(__file__).parent.parent / "data" / "profile_dashboard.png"\n\nPROFILE_QUERY = """\nquery userProfile($username: String!) {\n  matchedUser(username: $username) {\n    username\n    profile {\n      ranking\n      reputation\n      starRating\n    }\n    submitStats: submitStatsGlobal {\n      acSubmissionNum {\n        difficulty\n        count\n        submissions\n      }\n      totalSubmissionNum {\n        difficulty\n        count\n        submissions\n      }\n    }\n    badges {\n      id\n      displayName\n    }\n  }\n  allQuestionsCount {\n    difficulty\n    count\n  }\n}\n"""\n\n\ndef fetch_profile() -> dict:\n    payload = {\n        "query": PROFILE_QUERY,\n        "variables": {"username": LEETCODE_USERNAME},\n    }\n    resp = requests.post(GRAPHQL_URL, json=payload, headers=HEADERS, timeout=15)\n    resp.raise_for_status()\n    data = resp.json()\n    if "errors" in data:\n        raise RuntimeError(f"GraphQL error: {data[\'errors\']}")\n    return data["data"]\n\n\ndef to_dict_by_difficulty(entries: list[dict]) -> dict:\n    return {e["difficulty"]: e for e in entries}\n\n\ndef print_summary(data: dict):\n    user = data["matchedUser"]\n    profile = user["profile"]\n    ac_by_diff = to_dict_by_difficulty(user["submitStats"]["acSubmissionNum"])\n    total_by_diff = to_dict_by_difficulty(user["submitStats"]["totalSubmissionNum"])\n    all_questions = to_dict_by_difficulty(data["allQuestionsCount"])\n\n    solved_total = ac_by_diff.get("All", {}).get("count", 0)\n    submissions_total = total_by_diff.get("All", {}).get("submissions", 0)\n    accepted_submissions = ac_by_diff.get("All", {}).get("submissions", 0)\n    acceptance_rate = (\n        (accepted_submissions / submissions_total * 100) if submissions_total else 0\n    )\n\n    console.print(Panel.fit(\n        f"[bold cyan]{user[\'username\']}[/bold cyan]\\n"\n        f"Global Ranking: [bold]{profile[\'ranking\']}[/bold]\\n"\n        f"Reputation: {profile[\'reputation\']}  |  Star Rating: {profile[\'starRating\']}",\n        title="LeetCode Profile",\n    ))\n\n    table = Table(title="Problems Solved by Difficulty")\n    table.add_column("Difficulty")\n    table.add_column("Solved", justify="right")\n    table.add_column("Total Available", justify="right")\n    table.add_column("% of Difficulty Solved", justify="right")\n\n    for diff in ["Easy", "Medium", "Hard"]:\n        solved = ac_by_diff.get(diff, {}).get("count", 0)\n        total = all_questions.get(diff, {}).get("count", 0)\n        pct = (solved / total * 100) if total else 0\n        table.add_row(diff, str(solved), str(total), f"{pct:.1f}%")\n\n    console.print(table)\n    console.print(f"\\n[bold]Total solved:[/bold] {solved_total}")\n    console.print(f"[bold]Acceptance rate:[/bold] {acceptance_rate:.1f}%")\n\n    badges = user.get("badges", [])\n    if badges:\n        console.print(f"\\n[bold]Badges ({len(badges)}):[/bold]")\n        for b in badges:\n            console.print(f"  • {b[\'displayName\']}")\n    else:\n        console.print("\\n[bold]Badges:[/bold] none yet")\n\n    return {\n        "username": user["username"],\n        "ranking": profile["ranking"],\n        "solved_total": solved_total,\n        "acceptance_rate": acceptance_rate,\n        "ac_by_diff": ac_by_diff,\n        "all_questions": all_questions,\n        "badges": badges,\n    }\n\n\ndef render_dashboard(summary: dict):\n    """Renders a 3-panel PNG dashboard: solved-vs-total bars, donut, badges."""\n    diffs = ["Easy", "Medium", "Hard"]\n    solved = [summary["ac_by_diff"].get(d, {}).get("count", 0) for d in diffs]\n    totals = [summary["all_questions"].get(d, {}).get("count", 0) for d in diffs]\n    colors = ["#00b8a3", "#ffc01e", "#ff375f"]\n\n    fig, axes = plt.subplots(1, 3, figsize=(15, 5))\n    fig.suptitle(\n        f"LeetCode Dashboard — {summary[\'username\']}  "\n        f"(Rank #{summary[\'ranking\']:,})",\n        fontsize=14, fontweight="bold",\n    )\n\n    # Panel 1: solved vs total per difficulty\n    ax = axes[0]\n    x = range(len(diffs))\n    ax.bar(x, totals, color="#e0e0e0", label="Total available")\n    ax.bar(x, solved, color=colors, label="Solved")\n    ax.set_xticks(list(x))\n    ax.set_xticklabels(diffs)\n    ax.set_title("Solved vs Available")\n    ax.legend(fontsize=8)\n    for i, (s, t) in enumerate(zip(solved, totals)):\n        ax.text(i, t + max(totals) * 0.02, f"{s}/{t}", ha="center", fontsize=9)\n\n    # Panel 2: donut chart of solved distribution by difficulty\n    ax = axes[1]\n    if sum(solved) > 0:\n        ax.pie(\n            solved, labels=diffs, autopct="%1.0f%%", colors=colors,\n            wedgeprops=dict(width=0.4), startangle=90,\n        )\n    ax.set_title(f"Solved Distribution\\n(Total: {summary[\'solved_total\']})")\n\n    # Panel 3: acceptance rate gauge (simple bar)\n    ax = axes[2]\n    rate = summary["acceptance_rate"]\n    ax.barh(["Acceptance Rate"], [100], color="#e0e0e0")\n    ax.barh(["Acceptance Rate"], [rate], color="#00b8a3")\n    ax.set_xlim(0, 100)\n    ax.text(rate + 2, 0, f"{rate:.1f}%", va="center", fontsize=11, fontweight="bold")\n    ax.set_title("Acceptance Rate")\n    ax.set_xlabel("%")\n\n    plt.tight_layout()\n    OUTPUT_CHART.parent.mkdir(parents=True, exist_ok=True)\n    plt.savefig(OUTPUT_CHART, dpi=150)\n    console.print(f"\\n[bold green]Dashboard image saved to:[/bold green] {OUTPUT_CHART}")\n\n\ndef main():\n    if not (LEETCODE_USERNAME and LEETCODE_SESSION and LEETCODE_CSRF):\n        raise EnvironmentError("Missing LEETCODE_USERNAME / LEETCODE_SESSION / LEETCODE_CSRF in .env")\n\n    data = fetch_profile()\n    summary = print_summary(data)\n    render_dashboard(summary)\n\n\nif __name__ == "__main__":\n    main()\n'


EXTRA_DIRS = [
    "leetcode-questions",
    "data",
]


def main():
    for rel_path, content in FILES.items():
        full_path = PROJECT_ROOT / rel_path
        full_path.parent.mkdir(parents=True, exist_ok=True)
        full_path.write_text(content, encoding="utf-8")
        print(f"Created: {full_path}")

    for d in EXTRA_DIRS:
        dir_path = PROJECT_ROOT / d
        dir_path.mkdir(parents=True, exist_ok=True)
        (dir_path / ".gitkeep").touch()
        print(f"Created dir: {dir_path}")

    print(f"\nProject scaffolded at: {PROJECT_ROOT.resolve()}")
    print("Next steps:")
    print("  1. cd leetcode-ai-sync")
    print("  2. uv venv --python 3.11")
    print("  3. .\\venv\\Scripts\\Activate   (Windows)  or  source venv/bin/activate (macOS/Linux)")
    print("  4. uv pip install -r requirements.txt")
    print("  5. Copy-Item .env.example .env   (then fill in your credentials)")


if __name__ == "__main__":
    main()